-- PKG_DMF0008 — META 전환 확인 (조회 전용)
SET PAGESIZE 200 LINESIZE 300

-- DMF0008_GET_EDI_MST_REPAIR → PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR
SELECT API_ID, API_URL, CASE WHEN API_URL = 'PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR' THEN 'OK' ELSE 'NG' END CHK FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN ('P_DMF0008_REPAIR_GET');
SELECT 'PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR' PROC_NM,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR') NEW_ROWS,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE UPPER(PROC_NM) = 'DMF0008_GET_EDI_MST_REPAIR') STANDALONE_ROWS,
       (SELECT COUNT(*) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0008' AND OBJECT_NAME = 'P_DMF0008_GET_EDI_MST_REPAIR' AND DATA_LEVEL = 0) MEMBER_ARGS,
       (SELECT LISTAGG(COL_TP_CD, ',') WITHIN GROUP (ORDER BY SORT_ORD) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR') PROC_M_INOUT,
       (SELECT LISTAGG(REPLACE(IN_OUT, 'IN/OUT', 'INOUT'), ',') WITHIN GROUP (ORDER BY POSITION) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0008' AND OBJECT_NAME = 'P_DMF0008_GET_EDI_MST_REPAIR' AND DATA_LEVEL = 0) MEMBER_INOUT
  FROM DUAL;

